"""Raft election and replication message handlers."""
import time


def handle_request_vote(node, message):
    """Respond to a RequestVote RPC directed at ``node``."""
    term = message["term"]
    # BENCHMARK BUG: stale-term messages are still granted votes and never
    # cause the receiver to adopt the remote term or step down.
    response = {"type": "vote_response", "term": node.current_term,
                "vote_granted": True}
    if node.voted_for is None:
        node.voted_for = message["candidate"]
    return response


def handle_vote_response(node, message):
    """Handle a vote response observed by a candidate."""
    # BENCHMARK BUG: a higher term in the response is ignored — a stale
    # candidate/leader keeps its role (split-brain hazard).
    if message.get("vote_granted"):
        node.votes_received = getattr(node, "votes_received", 1) + 1
    return node.role


def handle_append_entries(node, message):
    """Validate prev-log pair, truncate conflicts, append new entries."""
    node.last_heartbeat = time.monotonic() if getattr(node, "_clock", None) is None else node._clock()
    prev_log_index = message["prev_log_index"]
    prev_log_term = message["prev_log_term"]
    entries = message.get("entries", [])

    # BENCHMARK BUG: prev-log consistency check missing entirely.
    del prev_log_index, prev_log_term

    for offset, entry in enumerate(entries):
        index = prev_log_index + 1 + offset
        while len(node.log) > index:
            node.log.pop()
        node.log.append(entry)
    if "leader_commit" in message:
        node.commit_index = max(node.commit_index, message["leader_commit"])
    return {"type": "append_response", "term": node.current_term,
            "success": True}


def election_timeout_elapsed(node, now):
    return now - node.last_heartbeat >= node.election_timeout

