"""Raft node state."""


class RaftNode:
    def __init__(self, node_id, election_timeout=5.0):
        self.node_id = node_id
        self.role = "FOLLOWER"
        self.current_term = 0
        self.voted_for = None
        self.log = []            # list of {"term": int, "cmd": str}
        self.commit_index = -1
        self.last_heartbeat = 0.0
        self.election_timeout = float(election_timeout)

    def become_follower(self, term):
        self.role = "FOLLOWER"
        self.current_term = term
        self.voted_for = None

    def become_candidate(self, term):
        self.role = "CANDIDATE"
        self.current_term = term
        self.voted_for = self.node_id

    def become_leader(self):
        if self.role == "CANDIDATE":
            self.role = "LEADER"

    def last_log_index(self):
        return len(self.log) - 1

    def last_log_term(self):
        return self.log[-1]["term"] if self.log else 0

    def entry_at(self, index):
        """0-based log access; returns None when out of range."""
        if 0 <= index < len(self.log):
            return self.log[index]
        return None

