"""Deterministic in-memory message transport for scripted scenarios."""


class InMemoryNetwork:
    def __init__(self):
        self.nodes = {}
        self.queue = []
        self.delivered = []

    def register(self, *nodes):
        for node in nodes:
            self.nodes[node.node_id] = node

    def send(self, src, dst_id, payload):
        self.queue.append({"src": src, "dst": dst_id, "payload": dict(payload)})

    def deliver_all(self):
        handlers = {
            "request_vote": "handle_request_vote",
            "vote_response": "handle_vote_response",
            "append_entries": "handle_append_entries",
            "append_response": "handle_append_response",
        }
        from . import election

        while self.queue:
            envelope = self.queue.pop(0)
            dst = self.nodes[envelope["dst"]]
            kind = envelope["payload"]["type"]
            handler_name = handlers[kind]
            if handler_name == "handle_request_vote":
                response = election.handle_request_vote(dst, envelope["payload"])
            elif handler_name == "handle_vote_response":
                response_role = election.handle_vote_response(dst, envelope["payload"])
                response = {"type": "noop", "role": response_role}
            elif handler_name == "handle_append_entries":
                response = election.handle_append_entries(dst, envelope["payload"])
            else:
                response = {"type": "noop"}
            self.delivered.append((envelope, response))
            yield dst, response

